typedef unsigned int u_int;
typedef float sceVu0FMATRIX[4][4];

class nglVector
{
public:
  float x, y, z, w;
  inline float& operator[](int i) { return (&x)[i]; }
  inline const float& operator[](int i) const { return (&x)[i]; }
} __attribute__((aligned (16)));

class nglMatrix
{
public:
  nglVector x, y, z, w;
  inline nglVector& operator[](int i) { return (&x)[i]; }
  inline const nglVector& operator[](int i) const { return (&x)[i]; }
} __attribute__((aligned (16)));

class vector_t
{
public:
  float x, y, z;
  vector_t(float _x, float _y, float _z);
};

class point_t
{
public:
  float x, y, z;
  point_t(float _x, float _y, float _z);
};

class transform_t
{
public:
  point_t operator*(const point_t&) const;
  vector_t operator*(const vector_t&) const;
};

#define NGLCLIP_MAX 6
struct nglScene
{
  char Prefix[32];
  nglMatrix ViewToWorld;
  nglMatrix ViewToScreen;
  nglMatrix ViewToClip;
  nglMatrix ClipToScreen;
  nglMatrix WorldToView;
  nglMatrix WorldToScreen;
  nglMatrix WorldToClip;
  nglMatrix ViewToScreenNoFTOI;
  nglMatrix WorldToScreenNoFTOI;
  char Middle[672];
  nglVector ClipPlanes[NGLCLIP_MAX];
  nglVector WorldClipPlanes[NGLCLIP_MAX];
  nglVector GBClipPlanes[NGLCLIP_MAX];
  nglVector WorldGBClipPlanes[NGLCLIP_MAX];
  nglVector ViewPos;
  nglVector ViewDir;
};

extern nglScene* nglCurScene;
extern void sceVu0CopyMatrix(sceVu0FMATRIX, sceVu0FMATRIX);
extern void sceVu0InversMatrix(sceVu0FMATRIX, sceVu0FMATRIX);
extern void sceVu0MulMatrix(sceVu0FMATRIX, sceVu0FMATRIX, sceVu0FMATRIX);
void nglApplyMatrixPlane(nglVector&, nglMatrix&, nglVector&);
#define SCE_MATRIX(x) ((float(*)[4])(float*)&(x))

void nglSetWorldToViewMatrix( const nglMatrix& WorldToView )
{
  sceVu0CopyMatrix( SCE_MATRIX(nglCurScene->WorldToView), SCE_MATRIX(WorldToView) );
  sceVu0InversMatrix( SCE_MATRIX(nglCurScene->ViewToWorld), SCE_MATRIX(nglCurScene->WorldToView) );
  sceVu0MulMatrix( SCE_MATRIX(nglCurScene->WorldToScreen), SCE_MATRIX(nglCurScene->ViewToScreen), SCE_MATRIX(nglCurScene->WorldToView) );
  sceVu0MulMatrix( SCE_MATRIX(nglCurScene->WorldToScreenNoFTOI), SCE_MATRIX(nglCurScene->ViewToScreenNoFTOI), SCE_MATRIX(nglCurScene->WorldToView) );
  sceVu0MulMatrix( SCE_MATRIX(nglCurScene->WorldToClip), SCE_MATRIX(nglCurScene->ViewToClip), SCE_MATRIX(nglCurScene->WorldToView) );
  for ( int i = 0; i < NGLCLIP_MAX; i++ )
  {
    nglApplyMatrixPlane( nglCurScene->WorldClipPlanes[i], nglCurScene->ViewToWorld, nglCurScene->ClipPlanes[i] );
    nglApplyMatrixPlane( nglCurScene->WorldGBClipPlanes[i], nglCurScene->ViewToWorld, nglCurScene->GBClipPlanes[i] );
  }

  nglCurScene->ViewPos = *(transform_t*)&nglCurScene->ViewToWorld * point_t( 0, 0, 0 );
  nglCurScene->ViewDir = *(transform_t*)&nglCurScene->ViewToWorld * vector_t( 0, 0, 1 );
}
